import { useEffect } from "react";

const CANDIDATES =
  "#main-content section, #main-content article, #main-content .home-focus-grid > *";
const SKIP = ".campus-hero, .campus-hero *, [role='dialog'] *, [data-no-reveal], [data-no-reveal] *";

/* Blocks below the fold fade and rise into place as they scroll into view. Anything
   already visible is left alone, so nothing flashes on load. Off when motion is off. */
export function useScrollReveal(page, motionPreference, systemReduced) {
  useEffect(() => {
    const main = document.getElementById("main-content");
    // Off in the app's own motion setting means no reveal. A system "reduce motion"
    // preference keeps the reveal as a plain fade, with no sliding.
    if (!main || motionPreference === "off" || !window.IntersectionObserver)
      return undefined;
    main.setAttribute("data-reveal-mode", systemReduced ? "fade" : "rise");

    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.setAttribute("data-reveal", "in");
          io.unobserve(entry.target);
        });
      },
      { rootMargin: "0px 0px -8% 0px", threshold: 0.05 },
    );

    const tag = () => {
      const seen = new Set();
      main.querySelectorAll(CANDIDATES).forEach((el) => {
        if (el.hasAttribute("data-reveal") || el.matches(SKIP)) return;
        // Reveal the outer block only; its children come with it.
        if (el.parentElement?.closest("[data-reveal]")) return;
        const rect = el.getBoundingClientRect();
        if (rect.top < window.innerHeight * 0.92) {
          el.setAttribute("data-reveal", "in");
          return;
        }
        const siblings = seen.has(el.parentElement) ? 1 : 0;
        seen.add(el.parentElement);
        el.style.setProperty("--reveal-delay", `${siblings * 60}ms`);
        el.setAttribute("data-reveal", "out");
        io.observe(el);
      });
    };

    tag();
    const mo = new MutationObserver(() => tag());
    mo.observe(main, { childList: true, subtree: true });
    return () => {
      main.removeAttribute("data-reveal-mode");
      mo.disconnect();
      io.disconnect();
      main.querySelectorAll("[data-reveal]").forEach((el) => {
        el.removeAttribute("data-reveal");
        el.style.removeProperty("--reveal-delay");
      });
    };
  }, [page, motionPreference, systemReduced]);
}
